IF OBJECT_ID('tempdb..#seed_skip') IS NULL AND @@TRANCOUNT > 0
BEGIN
    DECLARE @today DATETIME2 = (SELECT today FROM #seed_ctx);
    SET IDENTITY_INSERT movies ON;
    INSERT INTO movies (movie_id, title, description, duration, genre, release_date, status)
    SELECT v.movie_id, v.title, v.description, v.duration, v.genre, DATEADD(DAY, v.rel, CAST(@today AS DATE)), v.status
    FROM (VALUES
        (1,N'Summer Hearts in a Small Town',N'เรื่องราวของสถาปนิกสาวที่เพิ่งอกหัก ซึ่งได้โอกาสแก้ไขความเข้าใจผิดเมื่อสิบปีก่อน ภาพสวยและเพลงประกอบที่ติดหู',102,'Romance',-889,'inactive'),
        (2,N'ห้องเช่าต้องสาป',N'เรื่องราวของพยาบาลเวรดึกที่พบว่าห้องเก่าชั้นสามไม่เคยมีใครกล้าเปิด บรรยากาศน่ากลัวที่ค่อย ๆ บีบหัวใจ',95,'Horror',-644,'inactive'),
        (3,N'The Echo of Strangers',N'เรื่องราวของพี่น้องสองคนที่ไม่ได้คุยกันมานาน ซึ่งต้องเริ่มต้นใหม่หลังสูญเสียคนสำคัญ ภาพสะท้อนความสัมพันธ์ของคนในครอบครัว',158,'Drama',-599,'inactive'),
        (4,N'The Great Reunion Mix-Up',N'เรื่องราวของก๊วนป้า ๆ ที่ชอบเข้าไปยุ่งเรื่องชาวบ้าน ซึ่งต้องจัดงานแต่งงานให้เสร็จภายในสามวัน คอมเมดี้ที่ดูได้ทั้งครอบครัว',115,'Comedy',-49,'active'),
        (5,N'Binary Paradox',N'เรื่องราวของนักวิทยาศาสตร์หญิงในสถานีวิจัยใต้ทะเลที่ได้รับสัญญาณปริศนาจากดาวที่ไม่มีใครอาศัย ไซไฟที่ตั้งคำถามถึงความเป็นมนุษย์',142,'Sci-Fi',-1007,'inactive'),
        (6,N'My Neighbor Is a Robot',N'เรื่องราวของก๊วนป้า ๆ ที่ชอบเข้าไปยุ่งเรื่องชาวบ้าน ซึ่งต้องจัดงานแต่งงานให้เสร็จภายในสามวัน มุกฮาที่ซ้อนกันจนหยุดหัวเราะไม่ได้',119,'Comedy',-571,'inactive'),
        (7,N'The Silent Elevator',N'เรื่องราวของกลุ่มเพื่อนนักศึกษาที่พบว่าห้องเก่าชั้นสามไม่เคยมีใครกล้าเปิด สยองขวัญที่ทำให้ไม่กล้าหันหลังกลับ',111,'Horror',-1292,'inactive'),
        (8,N'Inside the Old Printing House',N'เรื่องราวของเกษตรกรรุ่นใหม่ที่ที่ปรับตัวต่อสภาพอากาศที่ผันผวน ภาพจริงและเสียงจริงจากพื้นที่',88,'Documentary',-1055,'inactive'),
        (9,N'Frozen Redemption',N'เรื่องราวของหน่วยกู้ภัยสาวมือฉมังที่ต้องหยุดแผนวางระเบิดก่อนรุ่งสาง แอ็กชันเต็มพิกัดที่มีเวลาเหลือเพียงไม่กี่ชั่วโมง',117,'Action',-1014,'inactive'),
        (10,N'The Weight of the Last Train',N'เรื่องราวของชายชราผู้เปิดร้านซ่อมนาฬิกาที่ได้พบจดหมายฉบับหนึ่งที่เปลี่ยนทุกอย่าง ภาพสะท้อนความสัมพันธ์ของคนในครอบครัว',104,'Drama',-1080,'inactive'),
        (11,N'The Language of Old Friends',N'เรื่องราวของชายชราผู้เปิดร้านซ่อมนาฬิกาที่ต้องเลือกระหว่างความฝันกับความรับผิดชอบ ดราม่าที่ทำให้คิดถึงบ้านทันทีที่หนังจบ',122,'Drama',-522,'inactive'),
        (12,N'The Mirror of Strangers',N'เรื่องราวของลูกสาวที่กลับบ้านหลังจากจากไปนานสิบปี ซึ่งต้องเลือกระหว่างความฝันกับความรับผิดชอบ เรื่องเล่าอบอุ่นที่ว่าด้วยการให้อภัย',123,'Drama',-762,'inactive'),
        (13,N'Golden Hearts in the Rain',N'เรื่องราวของเจ้าของร้านกาแฟเล็ก ๆ ริมทะเลที่ได้โอกาสแก้ไขความเข้าใจผิดเมื่อสิบปีก่อน ภาพสวยและเพลงประกอบที่ติดหู',116,'Romance',-356,'active'),
        (14,N'เจ้านายของฉันเป็นแม่มด',N'เรื่องราวของก๊วนป้า ๆ ที่ชอบเข้าไปยุ่งเรื่องชาวบ้าน ซึ่งต้องแกล้งเป็นคู่รักเพื่อเอาตัวรอด คอมเมดี้ที่ดูได้ทั้งครอบครัว',118,'Comedy',-532,'inactive'),
        (15,N'Crimson Hunter',N'เรื่องราวของบอดี้การ์ดผู้เก็บตัวที่ถูกลากเข้าสู่ปฏิบัติการล่าข้ามประเทศ ทุกก้าวถูกจับตามองจากคนในองค์กร',106,'Action',-167,'inactive'),
        (16,N'The Memory of Home',N'เรื่องราวของครอบครัวเล็ก ๆ ในต่างจังหวัดที่ต้องเผชิญกับความลับที่ซ่อนมานาน ภาพสะท้อนความสัมพันธ์ของคนในครอบครัว',157,'Drama',-291,'inactive'),
        (17,N'Perfect Alibi',N'เรื่องราวของวิศวกรที่พบความลับของบริษัท ซึ่งถูกตามล่าเพราะรู้มากเกินไป ปมซ่อนเงื่อนที่คลี่คลายในฉากสุดท้าย',111,'Thriller',-22,'active'),
        (18,N'The Promise of Small Hours',N'เรื่องราวของลูกสาวที่กลับบ้านหลังจากจากไปนานสิบปี ซึ่งได้พบจดหมายฉบับหนึ่งที่เปลี่ยนทุกอย่าง ภาพสะท้อนความสัมพันธ์ของคนในครอบครัว',125,'Drama',-834,'inactive'),
        (19,N'The Silence of Old Friends',N'เรื่องราวของครอบครัวเล็ก ๆ ในต่างจังหวัดที่ต้องเลือกระหว่างความฝันกับความรับผิดชอบ การแสดงที่จริงใจและเรียบง่าย',119,'Drama',-1292,'inactive'),
        (20,N'Shadow Gambit',N'เรื่องราวของสายลับที่ปลดเกษียณแล้ว ซึ่งต้องพาเด็กคนหนึ่งฝ่าวงล้อมของมือปืน การตัดสินใจครั้งนี้อาจต้องแลกด้วยทุกอย่าง',105,'Action',-171,'inactive'),
        (21,N'ก๊วนยามป่วนเมือง',N'เรื่องราวของพนักงานออฟฟิศสุดซวยที่ถูกเข้าใจผิดว่าเป็นคนสำคัญจนเรื่องบานปลาย ความวุ่นวายที่ทำให้ฮาตั้งแต่ต้นจนจบ',106,'Comedy',-241,'inactive'),
        (22,N'The Shape of Distant Shores',N'เรื่องราวของลูกสาวที่กลับบ้านหลังจากจากไปนานสิบปี ซึ่งต้องเริ่มต้นใหม่หลังสูญเสียคนสำคัญ ดราม่าที่ทำให้คิดถึงบ้านทันทีที่หนังจบ',160,'Drama',-1107,'inactive'),
        (23,N'หมู่บ้านต้องสาป',N'เรื่องราวของกลุ่มเพื่อนนักศึกษาที่ติดอยู่ในอาคารที่ประตูทุกบานล็อกจากด้านนอก สยองขวัญที่ทำให้ไม่กล้าหันหลังกลับ',105,'Horror',-506,'inactive'),
        (24,N'คืนสุดท้ายที่โรงเรียนเก่า',N'เรื่องราวของทีมงานถ่ายสารคดีสายมูที่พบว่าห้องเก่าชั้นสามไม่เคยมีใครกล้าเปิด ผีไทยที่ทั้งเศร้าและน่ากลัว',91,'Horror',-1012,'inactive'),
        (25,N'My Boss Is a Secret Agent',N'เรื่องราวของนักเรียนใหม่ที่เข้าใจอะไรผิดไปหมด ซึ่งถูกเข้าใจผิดว่าเป็นคนสำคัญจนเรื่องบานปลาย มุกฮาที่ซ้อนกันจนหยุดหัวเราะไม่ได้',91,'Comedy',-467,'inactive'),
        (26,N'ตำนานพระจันทร์สีเลือด',N'เรื่องราวของเด็กหญิงที่พบประตูสู่เมืองลับ ซึ่งต้องออกเดินทางตามหาแก้วศักดิ์สิทธิ์ทั้งเจ็ด การผจญภัยที่เต็มไปด้วยมิตรภาพ',139,'Fantasy',-856,'active'),
        (27,N'นกฮูกน้อยผจญภัย',N'เรื่องราวของลูกช้างตัวน้อยที่ต้องพิสูจน์ว่าตัวเล็กก็ทำเรื่องใหญ่ได้ ภาพสีสดใสและเพลงน่ารัก',93,'Animation',-1314,'inactive'),
        (28,N'Oops, We Inherited a Noodle Shop',N'เรื่องราวของพนักงานออฟฟิศสุดซวยที่ต้องจัดงานแต่งงานให้เสร็จภายในสามวัน เรื่องวุ่น ๆ ที่จบลงด้วยน้ำตาแห่งความสุข',99,'Comedy',-1516,'inactive'),
