        (30,N'ก๊วนเพื่อนซี้ป่วนเมือง',N'เรื่องราวของก๊วนป้า ๆ ที่ชอบเข้าไปยุ่งเรื่องชาวบ้าน ซึ่งต้องแกล้งเป็นคู่รักเพื่อเอาตัวรอด ความวุ่นวายที่ทำให้ฮาตั้งแต่ต้นจนจบ',106,'Comedy',-690,'inactive'),
