        (36,N'ฤดูที่เราเติบโต',N'เรื่องราวของหญิงสาวที่ต้องดูแลพ่อป่วย ซึ่งต้องกลับไปเผชิญอดีตที่พยายามลืม เรื่องเล่าอบอุ่นที่ว่าด้วยการให้อภัย',138,'Drama',-411,'active'),
