        (39,N'คืนสุดท้ายที่ตลาดเก่า',N'เรื่องราวของกลุ่มเพื่อนนักศึกษาที่เริ่มเห็นเงาประหลาดในกระจกทุกบาน ผีไทยที่ทั้งเศร้าและน่ากลัว',109,'Horror',-1312,'inactive'),
        (40,N'Double Evidence',N'เรื่องราวของนักสืบเอกชนผู้เก็บตัวที่ต้องตามหาความจริงของคดีที่ถูกปิดไปแล้ว ทุกคนมีความลับและทุกความลับมีราคา',124,'Thriller',-963,'inactive'),
