        (43,N'ทางกลับบ้านของชาวประมง',N'เรื่องราวของหญิงสาวที่ต้องดูแลพ่อป่วย ซึ่งต้องตัดสินใจครั้งสำคัญของชีวิต ดราม่าที่ทำให้คิดถึงบ้านทันทีที่หนังจบ',106,'Drama',-167,'active'),
