        (47,N'Tender Hearts in Late Autumn',N'เรื่องราวของช่างภาพหนุ่มที่เดินทางตลอดเวลา ซึ่งต้องทำงานร่วมกันทั้งที่ไม่ชอบหน้ากัน ภาพสวยและเพลงประกอบที่ติดหู',117,'Romance',-125,'inactive'),
