        (49,N'The Song of Silver Dunes',N'เรื่องราวของพ่อมดชราที่ลืมคาถาสำคัญ ซึ่งต้องข้ามป่าต้องห้ามเพื่อช่วยเมืองที่กำลังเลือนหาย ตำนานที่เล่าต่อกันมาหลายชั่วอายุคน',142,'Fantasy',-637,'inactive'),
        (50,N'Lethal Pursuit',N'เรื่องราวของหน่วยกู้ภัยสาวมือฉมังที่ต้องไล่ล่าแก๊งค้าอาวุธกลางเมืองหลวง การตัดสินใจครั้งนี้อาจต้องแลกด้วยทุกอย่าง',160,'Action',-196,'inactive'),
        (51,N'ฝนตกที่สถานีรถไฟ',N'เรื่องราวของสถาปนิกสาวที่เพิ่งอกหัก ซึ่งต้องตัดสินใจว่าจะเดินตามหัวใจหรือไม่ ความรักที่ไม่ต้องมีคำพูดมากมาย',118,'Romance',-397,'inactive'),
        (52,N'Final Horizon',N'เรื่องราวของทหารพรานที่ถูกใส่ร้าย ซึ่งต้องพาเด็กคนหนึ่งฝ่าวงล้อมของมือปืน แอ็กชันเต็มพิกัดที่มีเวลาเหลือเพียงไม่กี่ชั่วโมง',116,'Action',-133,'inactive'),
        (53,N'Iron Convoy',N'เรื่องราวของสายลับที่ปลดเกษียณแล้ว ซึ่งต้องปกป้องพยานสำคัญตลอด 24 ชั่วโมง แอ็กชันเต็มพิกัดที่มีเวลาเหลือเพียงไม่กี่ชั่วโมง',152,'Action',-1461,'inactive'),
        (54,N'Falling Alibi',N'เรื่องราวของนักสืบเอกชนผู้เก็บตัวที่ต้องไขปริศนาก่อนจะมีเหยื่อรายต่อไป ระทึกขวัญที่ต้องจับตาทุกรายละเอียด',116,'Thriller',-626,'inactive'),
        (55,N'Coco and the Rainbow Bridge',N'เรื่องราวของปลาหมึกจอมซนที่ออกเดินทางไปตามหาดาวตกที่หล่นลงป่า เรื่องราวมิตรภาพที่อบอุ่น',103,'Animation',-1280,'inactive'),
        (56,N'Kiko and the Singing Lighthouse',N'เรื่องราวของเต่าน้อยผู้ฝันอยากบินที่ได้เป็นเพื่อนกับเด็กหญิงที่ฟังภาษาสัตว์ออก การ์ตูนสนุกสำหรับเด็กและผู้ใหญ่',92,'Animation',-1406,'inactive'),
