        (58,N'ใครฆ่าเจ้าของโรงแรม',N'เรื่องราวของนักสืบเอกชนผู้เก็บตัวที่ถูกตามล่าเพราะรู้มากเกินไป ระทึกขวัญที่ต้องจับตาทุกรายละเอียด',105,'Thriller',-251,'inactive'),
