        (60,N'ฤดูที่ทุ่งข้าวเปลี่ยนสี',N'เรื่องราวของชายชราผู้เปิดร้านซ่อมนาฬิกาที่ต้องเผชิญกับความลับที่ซ่อนมานาน ดราม่าที่ทำให้คิดถึงบ้านทันทีที่หนังจบ',129,'Drama',-1150,'inactive'),
