        (110,N'ฤดูร้อนของฉันกับเธอ',N'เรื่องราวของสถาปนิกสาวที่เพิ่งอกหัก ซึ่งได้โอกาสแก้ไขความเข้าใจผิดเมื่อสิบปีก่อน ภาพสวยและเพลงประกอบที่ติดหู',96,'Romance',-750,'inactive'),
        (111,N'Savage Hunter',N'เรื่องราวของหน่วยกู้ภัยสาวมือฉมังที่พบว่าคนใกล้ตัวคือผู้อยู่เบื้องหลังทุกอย่าง ทุกก้าวถูกจับตามองจากคนในองค์กร',147,'Action',-1581,'active'),
        (112,N'Borrowed Hearts in Another Life',N'เรื่องราวของสถาปนิกสาวที่เพิ่งอกหัก ซึ่งต้องตัดสินใจว่าจะเดินตามหัวใจหรือไม่ เรื่องรักละมุนที่เหมาะกับการดูเป็นคู่',113,'Romance',-1386,'inactive'),
        (113,N'วันสุดท้ายของฉันกับเธอ',N'เรื่องราวของคู่รักเก่าที่กลับมาพบกันอีกครั้ง ซึ่งได้พบกันโดยบังเอิญในฤดูฝน ความรักที่ไม่ต้องมีคำพูดมากมาย',95,'Romance',-1242,'inactive'),
        (114,N'คืนสุดท้ายที่สะพานข้ามคลอง',N'เรื่องราวของครอบครัวที่เพิ่งย้ายบ้าน ซึ่งเริ่มเห็นเงาประหลาดในกระจกทุกบาน ไม่แนะนำให้ดูคนเดียว',102,'Horror',-996,'inactive'),
        (115,N'The Distance of Strangers',N'เรื่องราวของพี่น้องสองคนที่ไม่ได้คุยกันมานาน ซึ่งต้องเริ่มต้นใหม่หลังสูญเสียคนสำคัญ ภาพสะท้อนความสัมพันธ์ของคนในครอบครัว',100,'Drama',-966,'inactive'),
        (116,N'Momo and the Moonlight Train',N'เรื่องราวของกระต่ายนักประดิษฐ์ที่พบแผนที่ลับของสวนสนุกกลางป่า การ์ตูนสนุกสำหรับเด็กและผู้ใหญ่',96,'Animation',-1020,'inactive'),
