        (461,N'ก๊วนหมอป่วนเมือง',N'เรื่องราวของแม่ค้าตลาดสดกับลูกชายจอมซ่าที่ต้องจัดงานแต่งงานให้เสร็จภายในสามวัน เรื่องวุ่น ๆ ที่จบลงด้วยน้ำตาแห่งความสุข',92,'Comedy',-722,'inactive'),
