        (465,N'The Shape of Unspoken Words',N'เรื่องราวของครูหนุ่มในโรงเรียนชายขอบที่ต้องเลือกระหว่างความฝันกับความรับผิดชอบ การแสดงที่จริงใจและเรียบง่าย',157,'Drama',-907,'inactive'),
